'use strict';
const form=document.querySelector('#login-form'),error=document.querySelector('#login-error'),button=document.querySelector('#login-submit');
document.querySelector('#show-password').onclick=()=>{const input=document.querySelector('#password'),show=input.type==='password';input.type=show?'text':'password';document.querySelector('#show-password').textContent=show?'Hide':'Show';document.querySelector('#show-password').setAttribute('aria-label',show?'Hide password':'Show password')};
form.onsubmit=async event=>{event.preventDefault();error.hidden=true;button.disabled=true;button.textContent='Signing in…';try{const response=await fetch('/api/auth/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:form.email.value.trim(),password:form.password.value})});const result=await response.json();if(!response.ok)throw new Error(result.message||'Sign-in failed. Please try again.');const session=await fetch('/api/auth/me',{cache:'no-store',credentials:'same-origin'});if(!session.ok)throw new Error(session.status===401?'Your sign-in session could not be saved. Allow cookies for this site and try again.':'Unable to confirm your sign-in session. Please try again.');location.replace('/dashboard')}catch(e){error.textContent=e.message==='Failed to fetch'?'Unable to connect. Please try again.':e.message;error.hidden=false;button.disabled=false;button.textContent='Sign In'}};
